package com.smartgrocery.entity; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; private String category; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; private String unit="kg"; private boolean active=true; public Product(){} public Product(String n,String c,BigDecimal p,String u){name=n;category=c;price=p;unit=u;} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getUnit(){return unit;} public void setUnit(String v){unit=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }